/**
 * Regenerate src/styles/tokens/breakpoints.ts from the design
 * language's base.tokens.json, which lives in @colox/theme-builder
 * (the compile-time half owns the design-language sources; the runtime
 * half consumes the breakpoint values as JS constants).
 *
 * Breakpoints flow into a TS file — not CSS vars — because media
 * queries cannot read CSS custom properties: the responsive runtime
 * (ColoxThemeContext defaults, head bootstrap, matchMedia observer)
 * consumes the values in JS. breakpoints.ts is a generated file; run
 * this whenever base.tokens.json changes (the build chain does).
 *
 * Consumers who want different breakpoints do not regenerate anything:
 * the shipped runtime defaults serve as the contract, and ColoxTheme
 * accepts breakpoint overrides at the application level.
 */
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const themeRoot = fileURLToPath(new URL('../', import.meta.url));

function resolveBuilderPackage() {
  try {
    const packageJsonUrl = import.meta.resolve('@colox/theme-builder/package.json');
    return path.dirname(fileURLToPath(packageJsonUrl));
  } catch {
    console.error(
      'sync-breakpoints: cannot resolve @colox/theme-builder — install it as a devDependency of @colox/theme first.',
    );
    process.exit(1);
  }
}

const builderRoot = resolveBuilderPackage();
const baseTokensPath = path.join(builderRoot, 'src/styles/tokens/base.tokens.json');
const outPath = path.join(themeRoot, 'src/styles/tokens/breakpoints.ts');

let base;
try {
  base = JSON.parse(await readFile(baseTokensPath, 'utf8'));
} catch (err) {
  console.error(`sync-breakpoints: cannot read ${baseTokensPath}: ${err.message}`);
  process.exit(1);
}

const breakpoints = base.colox?.breakpoint ?? {};
if (Object.keys(breakpoints).length === 0) {
  console.error('sync-breakpoints: no breakpoints found in base.tokens.json');
  process.exit(1);
}

const kebab = (s) => s.replaceAll('_', '-');
const tsLines = [
  '// Generated by sync-breakpoints.mjs from @colox/theme-builder base.tokens.json.',
  '// Default contract breakpoints for the responsive runtime (ColoxThemeContext',
  '// defaults + head bootstrap script + matchMedia observer). Do not edit by hand.',
  'export const defaultBreakpoints = {',
  ...Object.entries(breakpoints).map(([name, token]) => `  ${kebab(name)}: '${token.$value}',`),
  '} as const;',
];
await mkdir(path.dirname(outPath), { recursive: true });
await writeFile(outPath, tsLines.join('\n') + '\n');
console.log('[ok] base.tokens.json breakpoints -> src/styles/tokens/breakpoints.ts');
